'''
# Read input from stdin and provide input before running code

name = raw_input('What is your name?\n')
print 'Hi, %s.' % name
'''
s=str(input());
q=int(input());
while(q!=0):
	buff=str(input());
	[l1,r1,l2,r2]=buff.split();
	if(s[int(l1)-1:int(r1)]==s[int(l2)-1:int(r2)]):
		print("Yes");
	else:
		print("No");
	q-=1;
